sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float factor;
uniform float speed;
uniform float baseRadius;
uniform float twist;
uniform float fade;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float r = max(length(d), 0.001);
    float e = log(r / baseRadius) / log(factor);
    float ph = e - time * speed;
    float k = floor(ph);
    float2 q = rot2(d, radians(twist) * k) / (pow(factor, k + time * speed));
    float4 s4 = texT(ctr + q);
    float edge = fract(ph);
    s4 = s4 * mix(1.0, smoothstep(0.0, 0.2, edge) * (1.0 - smoothstep(0.8, 1.0, edge)), fade);
    return fin(c, s4, opacity);
}
